import { createRoot } from 'react-dom/client';
import './index.css';
/**
 * Sample for Bar series
 */
import * as React from "react";
import { useEffect } from 'react';
import { Inject, Circular3DComponent, Circular3DSeriesCollectionDirective, Circular3DSeriesDirective, Circular3DDataLabel, Circular3DHighlight, Circular3DLegend, Circular3DTooltip, PieSeries3D } from '@syncfusion/ej2-react-charts';
import { Browser } from '@syncfusion/ej2-base';

export let data1 = [
    { 'x': 'Internet Explorer', y: 6.12, },
    { 'x': 'Chrome', y: 57.28, },
    { 'x': 'Safari', y: 4.73, },
    { 'x': 'QQ', y: 5.96, },
    { 'x': 'UC Browser', y: 4.37, },
    { 'x': 'Edge', y: 7.48, },
    { 'x': 'Others', y: 14.06, }
];
const SAMPLE_CSS = `
    .control-fluid {
        padding: 0px !important;
    }`;
/**
 * Donut sample
 */
const PieWithLegend = () => {
    const onChartLoad = (args) => {
        let chart = document.getElementById('charts');
        chart.setAttribute('title', '');
    };
    const load = (args) => {
        let selectedTheme = location.hash.split('/')[1];
        selectedTheme = selectedTheme ? selectedTheme : 'Material';
        args.chart.theme = (selectedTheme.charAt(0).toUpperCase() + selectedTheme.slice(1)).replace(/-dark/i, "Dark").replace(/contrast/i, 'Contrast');
    };
    return (<div className='control-pane'>
        <style>{SAMPLE_CSS}</style>
        <div className='control-section'>
            <div>
                <Circular3DComponent id='charts' style={{ textAlign: "center" }} legendSettings={{
            visible: true,
            enableHighlight: true,
            position: Browser.isDevice ? 'Bottom' : 'Right',
        }} highlightMode='Point' tilt={-35} enableRotation={true} load={load.bind(this)} title='Berlin 2023 Special Olympics Gold Medals' loaded={onChartLoad.bind(this)} tooltip={{ enable: true, format: '<b>${point.x}</b><br>Browser Share: <b>${point.y}%</b>', header: "" }}>
                    <Inject services={[PieSeries3D, Circular3DDataLabel, Circular3DLegend, Circular3DTooltip, Circular3DHighlight]}/>
                    <Circular3DSeriesCollectionDirective>
                        <Circular3DSeriesDirective dataSource={data1} xName='x' yName='y' explode={true} innerRadius='43%' explodeOffset='10%' radius='80%' dataLabel={{
            visible: true, position: 'Inside', template: '${point.y}%',
            font: { fontWeight: '600', color: '#ffffff' }, name: 'y', connectorStyle: { length: '20px' }
        }}>
                        </Circular3DSeriesDirective>
                    </Circular3DSeriesCollectionDirective>
                </Circular3DComponent>
            </div>
        </div>
    </div>);
};
export default PieWithLegend;

const root = createRoot(document.getElementById('sample'));
root.render(<PieWithLegend />);
